export async function captureCc(context = normalizeContext({ messages: [{ role: "user", content: "PING", timestamp: 1 }] }), options: any = {}, model: any = ccModel, onNormalized?: (event: any) => void) {
	return withCcHome(async () => {
		const { streamAnthropicCc } = await import("../../src/anthropic-cc/stream");
		const requests: Request[] = [];
		const events: any[] = [];
		const fetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
			const request = new Request(input, init);
			requests.push(request.clone());
			return options.fetch ? options.fetch(input, init) : new Response(sse, { headers: { "content-type": "text/event-stream" } });
		}) as typeof globalThis.fetch;
		const stream = streamAnthropicCc(model, context, { apiKey: "fixture-key", ...options, fetch });
		for await (const event of stream) { onNormalized?.(event); events.push(structuredClone(event)); }
		const message = await stream.result();
		const body = requests[0] ? await requests[0].json() as any : undefined;
		return { requests, body, events, message };
	});
}
